(function($){
'use strict';
var cfg=window.OneIdMaintenanceDeveloperAdmin||{},$root=$('.maintenance-developer-admin'),$duration=$('.maintenance-developer-duration'),draftKey='oneid_maintenance_developer_grant_draft_v1',revokeDraftKey='oneid_maintenance_developer_revoke_draft_v1';
if(!$root.length)return;
function esc(value){return $('<div>').text(value==null?'':value).html();}
function selectedReason(){var $selected=$('.maintenance-developer-reason-options button.is-selected'),value=String($selected.data('reason')||'');return value==='OTHER'?$.trim($('#maintenance_developer_reason').val()):value;}
function reviewData(){return{user:String($('#maintenance_developer_user_id').val()||''),userLabel:String($('#maintenance_developer_selected').text()||''),from:String($('#maintenance_developer_valid_from').val()||''),until:String($('#maintenance_developer_valid_until').val()||''),reason:selectedReason(),reference:$.trim($('#maintenance_developer_reference').val())};}
function valid(data){return !!data.user&&!!data.from&&!!data.until&&new Date(data.until)>new Date(data.from)&&data.reason.length>=10&&data.reference.length>=8;}
function saveDraft(data){try{data.savedAt=Date.now();window.sessionStorage.setItem(draftKey,JSON.stringify(data));}catch(ignore){}}
function clearDraft(){try{window.sessionStorage.removeItem(draftKey);}catch(ignore){}}
function loadDraft(){try{var raw=window.sessionStorage.getItem(draftKey),data=raw?JSON.parse(raw):null;if(!data||Date.now()-Number(data.savedAt||0)>600000||!valid(data)){clearDraft();return null;}return data;}catch(ignore){clearDraft();return null;}}
function generatedReference(){var d=new Date(),pad=function(v){return String(v).padStart(2,'0');};return 'ONEID-MD-'+d.getFullYear()+pad(d.getMonth()+1)+pad(d.getDate())+'-'+pad(d.getHours())+pad(d.getMinutes());}
function saveRevokeDraft(data){try{data.savedAt=Date.now();window.sessionStorage.setItem(revokeDraftKey,JSON.stringify(data));}catch(ignore){}}
function clearRevokeDraft(){try{window.sessionStorage.removeItem(revokeDraftKey);}catch(ignore){}}
function loadRevokeDraft(){try{var raw=window.sessionStorage.getItem(revokeDraftKey),data=raw?JSON.parse(raw):null;if(!data||Date.now()-Number(data.savedAt||0)>600000||Number(data.id)<1||Number(data.version)<1){clearRevokeDraft();return null;}return data;}catch(ignore){clearRevokeDraft();return null;}}
function skinRevokeAlert(){var alert=document.querySelector('.sweet-alert.showSweetAlert'),overlay=document.querySelector('.sweet-overlay');if(!alert)return;alert.classList.add('oneid-site-api-alert','oneid-site-api-alert--maintenance','oneid-md-revoke-alert');if(overlay)overlay.classList.add('oneid-site-api-overlay');var old=alert.querySelector('.oneid-site-api-eyebrow');if(old)old.parentNode.removeChild(old);var eyebrow=document.createElement('div'),tabEyebrow=$root.closest('.sso-config-panel').find('.sso-config-eyebrow').first().text();eyebrow.className='oneid-site-api-eyebrow';eyebrow.textContent=cfg.eyebrow||tabEyebrow||'Maintenance Access Control';var icon=alert.querySelector('.sa-icon');alert.insertBefore(eyebrow,icon||alert.firstChild);}
function modalMarkup(){return '<div id="maintenance_developer_review_modal" class="modal fade oneid-md-review-modal" tabindex="-1" role="dialog" aria-labelledby="maintenance_developer_review_title" aria-hidden="true"><div class="modal-dialog"><div class="modal-content oneid-sync-child-modal"><div class="oneid-md-review-header"><div class="oneid-md-review-heading"><span class="oneid-md-review-icon"><i class="fa fa-code"></i></span><div><small>'+esc(cfg.reviewIntro)+'</small><h4 id="maintenance_developer_review_title">'+esc(cfg.reviewTitle)+'</h4></div></div><span class="oneid-md-security-badge"><i class="fa fa-shield"></i> Admin Step-Up</span><button type="button" class="close" data-dismiss="modal" aria-label="Close">×</button></div><div class="modal-body oneid-md-review-body"><div class="oneid-md-review-lead"><i class="fa fa-info-circle"></i><p>'+esc(cfg.reviewIntro)+'</p></div><div class="oneid-md-review-grid"><section><span><i class="fa fa-user"></i></span><div><small>'+esc(cfg.reviewUser)+'</small><strong id="oneid_md_review_user"></strong></div></section><section><span><i class="fa fa-clock-o"></i></span><div><small>'+esc(cfg.reviewPeriod)+'</small><strong id="oneid_md_review_period"></strong></div></section><section><span><i class="fa fa-check-circle"></i></span><div><small>'+esc(cfg.reviewReason)+'</small><strong id="oneid_md_review_reason"></strong></div></section><section><span><i class="fa fa-tag"></i></span><div><small>'+esc(cfg.reviewReference)+'</small><strong id="oneid_md_review_reference"></strong></div></section></div><div class="oneid-md-stepup-note"><span><i class="fa fa-lock"></i></span><div><strong>Security Configuration Change</strong><p>'+esc(cfg.reviewIntro)+'</p></div></div><div id="oneid_md_review_error" class="alert alert-danger" hidden></div></div><div class="modal-footer oneid-sync-child-footer oneid-md-review-footer"><button type="button" class="btn btn-default" data-dismiss="modal"><i class="fa fa-arrow-left"></i> '+esc(cfg.cancel)+'</button><button type="button" class="btn btn-primary" id="oneid_md_confirm_grant"><i class="fa fa-shield"></i> '+esc(cfg.confirm)+'</button></div></div></div></div>';}
$('body').append(modalMarkup());
if($duration.length){$duration.prepend('<button type="button" data-hours="0.5">30 '+esc(cfg.minutes||'minutes')+'</button>');$duration.append('<button type="button" data-hours="8">8 '+esc(cfg.hours||'hours')+'</button><button type="button" data-hours="24">1 '+esc(cfg.day||'day')+'</button>');}
function showReview(data){var format=window.oneidMaintenanceDeveloperReadableDate||function(value){return value;};$('#oneid_md_review_user').text(data.userLabel);$('#oneid_md_review_period').text(format(data.from,false)+' — '+format(data.until,false));$('#oneid_md_review_reason').text(data.reason);$('#oneid_md_review_reference').text(data.reference);$('#oneid_md_review_error').prop('hidden',true).text('');$('#maintenance_developer_review_modal').data('grant',data).modal({backdrop:'static',keyboard:false});}
function restoreDraft(data){$('#maintenance_developer_user_id').val(data.user);$('#maintenance_developer_selected').text(data.userLabel);$('#maintenance_developer_valid_from').val(data.from);$('#maintenance_developer_valid_until').val(data.until);$('#maintenance_developer_reference').val(data.reference);$('#maintenance_developer_grant_card').prop('hidden',false);var $reason=$('.maintenance-developer-reason-options button').filter(function(){return String($(this).data('reason')||'')===data.reason;}).first();$('.maintenance-developer-reason-options button').removeClass('is-selected');if($reason.length){$reason.addClass('is-selected');$('#maintenance_developer_reason_other').prop('hidden',true);}else{$('.maintenance-developer-reason-options button[data-reason="OTHER"]').addClass('is-selected');$('#maintenance_developer_reason').val(data.reason);$('#maintenance_developer_reason_other').prop('hidden',false);}showReview(data);}
document.addEventListener('click',function(event){var button=event.target.closest&&event.target.closest('#maintenance_developer_grant');if(!button)return;event.preventDefault();event.stopImmediatePropagation();var data=reviewData();if(!valid(data)){window.swal(cfg.reviewTitle,cfg.validation,'warning');return;}showReview(data);},true);
$(document).on('click','#oneid_md_confirm_grant',function(){var $button=$(this),$modal=$('#maintenance_developer_review_modal'),data=$modal.data('grant')||{};$button.prop('disabled',true).attr('aria-busy','true');$.ajax({type:'POST',url:$root.data('api'),dataType:'json',headers:{'X-CSRF-Token':$root.data('csrf')},data:{admin_grant_maintenance_developer_access:'',user_id:data.user,valid_from:data.from,valid_until:data.until,change_reason:data.reason,change_reference:data.reference,confirmation:'GRANT MAINTENANCE ACCESS '+data.user}}).done(function(response){clearDraft();$modal.modal('hide');window.swal(cfg.success,response.code+' · '+response.correlation_id,'success');$('#maintenance_developer_grant_card').prop('hidden',true);$('#maintenance_developer_refresh').trigger('click');}).fail(function(xhr){var response=xhr.responseJSON||{},code=String(response.code||'MAINTENANCE_ACCESS_UNAVAILABLE');if(xhr.status===403&&code.indexOf('STEP_UP_')===0){saveDraft(data);window.location.href=$root.data('step-up-url');return;}$('#oneid_md_review_error').prop('hidden',false).text(code);}).always(function(){$button.prop('disabled',false).attr('aria-busy','false');});});
function revokePanel(data){return '<div class="oneid-md-revoke-panel"><div class="oneid-md-revoke-warning"><span><i class="fa fa-user-times"></i></span><div><strong>'+esc(cfg.revokeTitle)+'</strong><p>Grant #'+Number(data.id)+' · '+esc(cfg.reviewIntro)+'</p></div></div><label for="oneid_md_revoke_reason">'+esc(cfg.reasonLabel)+'</label><select id="oneid_md_revoke_reason" class="form-control"><option value="">'+esc(cfg.revokeReasonSelect)+'</option><option value="'+esc(cfg.revokeReasonComplete)+'">'+esc(cfg.revokeReasonComplete)+'</option><option value="'+esc(cfg.revokeReasonSecurity)+'">'+esc(cfg.revokeReasonSecurity)+'</option><option value="'+esc(cfg.revokeReasonChange)+'">'+esc(cfg.revokeReasonChange)+'</option><option value="OTHER">'+esc(cfg.revokeReasonOther)+'</option></select><textarea id="oneid_md_revoke_other" class="form-control" rows="3" minlength="10" maxlength="500" hidden></textarea><label for="oneid_md_revoke_reference">'+esc(cfg.referenceLabel)+'</label><input id="oneid_md_revoke_reference" class="form-control" maxlength="100" value="'+esc(data.reference||generatedReference())+'"></div>';}
function openRevoke(data){window.swal({title:cfg.revokeTitle,text:revokePanel(data),html:true,type:'warning',showCancelButton:true,confirmButtonColor:'#d9534f',confirmButtonText:cfg.confirmRevoke,cancelButtonText:cfg.cancel,closeOnConfirm:false,allowEscapeKey:false,allowOutsideClick:false},function(ok){if(!ok)return;var option=String($('#oneid_md_revoke_reason').val()||''),reason=option==='OTHER'?$.trim($('#oneid_md_revoke_other').val()):option,reference=$.trim($('#oneid_md_revoke_reference').val());if(reason.length<10||reference.length<8){window.swal.showInputError(cfg.validation);return false;}$.ajax({type:'POST',url:$root.data('api'),dataType:'json',headers:{'X-CSRF-Token':$root.data('csrf')},data:{admin_revoke_maintenance_developer_access:'',grant_id:data.id,configuration_version:data.version,change_reason:reason,change_reference:reference,confirmation:'REVOKE MAINTENANCE ACCESS '+data.id}}).done(function(response){clearRevokeDraft();window.swal(cfg.success,response.code+' · '+response.correlation_id,'success');$('#maintenance_developer_refresh').trigger('click');}).fail(function(xhr){var response=xhr.responseJSON||{},code=String(response.code||'MAINTENANCE_ACCESS_UNAVAILABLE');if(xhr.status===403&&code.indexOf('STEP_UP_')===0){saveRevokeDraft({id:data.id,version:data.version,reason:reason,reference:reference});window.location.href=$root.data('step-up-url');return;}window.swal.showInputError(code);});return false;});skinRevokeAlert();setTimeout(function(){if(data.reason){var predefined=$('#oneid_md_revoke_reason option[value="'+data.reason.replace(/"/g,'\\"')+'"]').length>0;$('#oneid_md_revoke_reason').val(predefined?data.reason:'OTHER');if(!predefined)$('#oneid_md_revoke_other').val(data.reason).prop('hidden',false);}},0);}
document.addEventListener('click',function(event){var button=event.target.closest&&event.target.closest('.md-revoke');if(!button)return;event.preventDefault();event.stopImmediatePropagation();openRevoke({id:Number($(button).data('id')),version:Number($(button).data('version')),reference:generatedReference()});},true);
$(document).on('change','#oneid_md_revoke_reason',function(){var other=String($(this).val())==='OTHER';$('#oneid_md_revoke_other').prop('hidden',!other);if(other)$('#oneid_md_revoke_other').focus();});
var returnContext=String(new URLSearchParams(window.location.search).get('step_up_return')||'');if(returnContext==='configuration_maintenance_developer'){var revokeDraft=loadRevokeDraft(),draft=loadDraft();if(revokeDraft){setTimeout(function(){openRevoke(revokeDraft);},350);}else if(draft){setTimeout(function(){restoreDraft(draft);},350);}}
})(jQuery);
